//! for small chevrons and checkmarks so their stroke matches at 10–12 pt).

use rune::Icon;

macro_rules! phosphor {
    ($name:ident, $d:expr) => {
        pub static $name: Icon = Icon { name: stringify!($name), view: 256.0, body: concat!(r#"<path d=""#, $d, r#"" fill="currentColor"/>"#) };
    };
}

