/// The icon for a layout, which the title bar's button shows for the note's own.
pub fn icon_of(layout: crate::map::Layout) -> &'static Icon {
    use crate::map::Layout;
    match layout {
        Layout::Right => &LAYOUT_RIGHT,
        Layout::Left => &LAYOUT_LEFT,
        Layout::Both => &LAYOUT_BOTH,
        Layout::Down => &LAYOUT_DOWN,
        Layout::Up => &LAYOUT_UP,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_phosphor_icon_rasterizes() {
        let all: &[&Icon] = &[
            &LAYOUT_RIGHT, &LAYOUT_LEFT, &LAYOUT_BOTH, &LAYOUT_DOWN, &LAYOUT_UP, &SIDEBAR_LEFT, &SIDEBAR_RIGHT, &SEARCH, &PLUS, &MINUS, &CLOSE, &CHEVRON_DOWN, &CHEVRON_UP, &CHEVRON_RIGHT, &FOLDER, &FOLDER_OPEN, &TAG, &GEAR, &EYE, &CODE, &FOCUS, &WIDEN, &NARROW, &HELP, &FIT, &RESET, &COPY, &PARAGRAPH, &TYPEWRITER, &FONT, &BOLD, &ITALIC, &STRIKE, &HEADING, &LINK, &WIKI, &BULLETS, &NUMBERS, &TASK, &QUOTE, &IMAGE, &LOCK, &INFO, &LIGHT_BULB, &IMPORTANT, &WARNING, &CAUTION, &CALENDAR, &CHECK, &PENCIL, &EXPAND, &TRASH, &FILE_TEXT,
        ];
        for ic in all {
            let cov = rune::text::icon_coverage(ic, 16);
            assert!(cov.iter().any(|&a| a > 0), "{} rasterized empty", ic.name);
        }
    }

    #[test]
    fn font_and_chevrons_are_optically_centered() {
        let centroid_dy = |ic: &Icon, sz: u32| -> f32 {
            let cov = rune::text::icon_coverage(ic, sz);
            let (mut sum_y, mut sum_w) = (0.0f32, 0.0f32);
            for y in 0..sz {
                for x in 0..sz {
                    let a = cov[(y * sz + x) as usize] as f32;
                    if a > 25.0 {
                        sum_y += y as f32 * a;
                        sum_w += a;
                    }
                }
            }
            assert!(sum_w > 0.0, "{} rendered empty", ic.name);
            (sum_y / sum_w) - (sz as f32 - 1.0) / 2.0
        };
        let font_dy = centroid_dy(&FONT, 15);
        assert!(font_dy.abs() <= 0.75, "FONT (Aa) vertical centroid dy={font_dy:+.2}px");
        let up_dy = centroid_dy(&CHEVRON_UP, 12);
        let down_dy = centroid_dy(&CHEVRON_DOWN, 12);
        assert!(up_dy.abs() <= 0.75, "CHEVRON_UP dy={up_dy:+.2}px");
        assert!(down_dy.abs() <= 0.75, "CHEVRON_DOWN dy={down_dy:+.2}px");
    }
}
